function splitLines(t){ return String(t||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;}); }
function parseDim(t){
  return splitLines(t).map(function(l){
    var i=l.indexOf(':'), j=l.indexOf('：');
    var pos=-1; if(i>=0&&(j<0||i<j)) pos=i; else if(j>=0) pos=j;
    var w=1; var k=l;
    if(pos>0){ k=l.slice(0,pos).trim(); var ws=l.slice(pos+1).trim(); var n=parseFloat(ws); if(!isNaN(n)&&n>0) w=n; }
    return {k:k, w:w};
  });
}
function buildRubric(o){
  o=o||{};
  var task=String(o.task||'').trim()||'（待填写评价任务）';
  var levels=splitLines(o.levels);
  if(!levels.length) levels=['优秀','良好','合格','不合格'];
  var dims=parseDim(o.dimensions);
  if(!dims.length) dims=[{k:'内容', w:1}];
  var weightSum=0; dims.forEach(function(d){ weightSum+=d.w; });
  var lvlNote={};
  levels.forEach(function(lv,idx){
    if(idx===0) lvlNote[lv]='（示范级）';
    else if(idx===levels.length-1) lvlNote[lv]='（需重点改进）';
    else lvlNote[lv]='';
  });
  var header='| 维度 | 权重 | '+levels.join(' | ')+' |';
  var sep='| --- | --- | '+levels.map(function(){return '---';}).join(' | ')+' |';
  var rows=dims.map(function(d){
    var cells=levels.map(function(lv){ return '在「'+d.k+'」方面达到 '+lv+' 等级要求'+lvlNote[lv]; });
    return '| '+d.k+' | '+d.w+' | '+cells.join(' | ')+' |';
  });
  var lines=[];
  lines.push('# 评分量规：'+task);
  lines.push('');
  lines.push('- 评价等级：'+levels.join(' / '));
  var wpct=dims.map(function(d){ return d.k+' '+Math.round(d.w/weightSum*100)+'%'; }).join('，');
  lines.push('- 权重分配：'+wpct+'（合计 100%）');
  lines.push('');
  lines.push(header);
  lines.push(sep);
  rows.forEach(function(r){ lines.push(r); });
  return {title:task+' 评分量规', dimCount:dims.length, levelCount:levels.length, weightSum:weightSum, markdown:lines.join('\n')};
}
var EXPORTS={splitLines:splitLines, parseDim:parseDim, buildRubric:buildRubric};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.GradingRubricForgePure = EXPORTS; }
